package cl.nexbyte.siger.institucional.nucleo;
import cl.nexbyte.siger.institucional.robustez.*;import java.nio.file.*;import java.time.*;import java.util.*;import org.flywaydb.core.Flyway;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import static org.junit.jupiter.api.Assertions.*;
class MateriasMigracionTest {
 @TempDir Path temp;
 @Test void actualiza153YPruebaConsultaRectificacionYRevocacion()throws Exception{
  String mysql=System.getProperty("siger.test.autoridad.mysql");if(mysql!=null&&!mysql.matches("jdbc:mysql://127\\.0\\.0\\.1:[5-6][0-9]{4}/siger_u15_test_[a-f0-9]{32}"))throw new IllegalStateException("MySQL descartable requerido");String url=mysql==null?"jdbc:h2:file:"+temp.resolve("nucleo").toAbsolutePath().toString().replace('\\','/')+";DB_CLOSE_ON_EXIT=FALSE;WRITE_DELAY=0":mysql+"_materia?sslMode=DISABLED&allowPublicKeyRetrieval=true&connectTimeout=3000&socketTimeout=10000";
  try(var before=new BaseJdbc(url,mysql==null?"sa":"root",mysql==null?"":System.getenv("SIGER_U15_TEST_MYSQL_PASSWORD"),2)){Flyway.configure().dataSource(before.sql.getDataSource()).locations("classpath:db/institucional/"+(mysql==null?"h2":"mysql")).target("15.3").cleanDisabled(true).load().migrate();}
  try(var d=new DatosNucleoTest(temp,mysql==null?null:url)){var m=new MateriasFixture(d,Clock.systemUTC());var c=m.caso();m.clasificar(c,0,"MAT_UPR",true);assertTrue(m.f.core.caso(m.f.a(m.upr),c).soloLectura());assertEquals(1,m.f.core.casos(m.f.a(m.upr),"",0,20).total());assertEquals(1,m.f.core.bandeja(m.f.a(m.upr)).casosAsignados());m.clasificar(c,1,"MAT_UPD",true);assertEquals(0,m.f.core.casos(m.f.a(m.upr),"",0,20).total());assertTrue(m.f.core.caso(m.f.a(m.upd),c).soloLectura());m.f.otorgar(m.f.headA,"COORDINADOR","AREA_B");m.f.otorgar(m.f.profA,"PROFESIONAL","AREA_B");m.f.core.cambiarArea(m.f.a(m.f.headA),UUID.randomUUID(),c,new ContratosNucleo.CambiarArea(2,"AREA_B","Cambio de área conserva materia y suspende consulta","AREA_A"));assertEquals(404,assertThrows(FalloTecnico.class,()->m.f.core.caso(m.f.a(m.upd),c)).status);m.publicar("SUSPENDIDA",m.f.end);var instruction=d.db.sql.queryForObject("SELECT id FROM access_instruction WHERE beneficiary_id=? AND scope_code='MATERIA' AND state='EJECUTADA'",String.class,m.upd);m.f.f.concesiones.revocar(m.f.f.revisor,UUID.randomUUID(),UUID.fromString(instruction),new cl.nexbyte.siger.institucional.identidad.ConcesionesInstitucionales.Decision(2,"Revocación de consulta en motor descartable"));assertEquals(404,assertThrows(FalloTecnico.class,()->m.f.core.caso(m.f.a(m.upd),c)).status);assertEquals(3,((List<?>)m.f.core.contextoMateria(m.f.a(m.f.headA),c).get("historial")).size());assertTrue(d.db.sql.queryForObject("SELECT COUNT(*) FROM matter_access_event",Long.class)>0);}
 }
 @Test void sqlEquivalente()throws Exception{try(var h=getClass().getResourceAsStream("/db/institucional/h2/V15_4__materias_y_consulta_regional.sql");var m=getClass().getResourceAsStream("/db/institucional/mysql/V15_4__materias_y_consulta_regional.sql")){assertNotNull(h);assertNotNull(m);assertArrayEquals(h.readAllBytes(),m.readAllBytes());}}
}
